import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {

    // 边，保存边权和左端点位置
    static class Edge implements Comparable<Edge> {
        int diff;
        int pos;

        Edge(int diff, int pos) {
            this.diff = diff;
            this.pos = pos;
        }

        @Override
        public int compareTo(Edge other) {
            return this.diff - other.diff;
        }
    }

    // 并查集，维护连通块大小
    static class DSU {
        int[] parent;
        int[] size;
        int maxSize;

        DSU(int n) {
            parent = new int[n + 1];
            size = new int[n + 1];
            for (int i = 1; i <= n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
            // 初始每个点单独成块，最大大小为 1
            maxSize = 1;
        }

        // 查找根节点，带路径压缩
        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        // 合并两个集合，并更新最大连通块大小
        void union(int x, int y) {
            int rx = find(x);
            int ry = find(y);

            if (rx == ry) {
                return;
            }

            // 按集合大小合并，小集合挂到大集合上
            if (size[rx] < size[ry]) {
                int temp = rx;
                rx = ry;
                ry = temp;
            }

            parent[ry] = rx;
            size[rx] += size[ry];

            if (size[rx] > maxSize) {
                maxSize = size[rx];
            }
        }
    }

    // 计算每个 k 对应的答案
    static int[] solveOneCase(int n, int[] arr) {
        Edge[] edges = new Edge[n - 1];

        // 构造相邻位置之间的边
        for (int i = 0; i < n - 1; i++) {
            int diff = Math.abs(arr[i] - arr[i + 1]);
            edges[i] = new Edge(diff, i + 1); // 连接位置 i+1 和 i+2
        }

        // 按边权从小到大排序
        Arrays.sort(edges);

        DSU dsu = new DSU(n);
        int[] ans = new int[n + 1];
        int idx = 0;

        // 枚举 k=1..n
        for (int k = 1; k <= n; k++) {
            // 将所有边权 <= k 的边加入图中
            while (idx < edges.length && edges[idx].diff <= k) {
                int pos = edges[idx].pos;
                dsu.union(pos, pos + 1);
                idx++;
            }

            // 当前最大连通块大小就是答案
            ans[k] = dsu.maxSize;
        }

        return ans;
    }

    public static void main(String[] args) throws Exception {
        FastReader fr = new FastReader();
        StringBuilder sb = new StringBuilder();

        int t = fr.nextInt();

        while (t-- > 0) {
            int n = fr.nextInt();
            int[] arr = new int[n];

            for (int i = 0; i < n; i++) {
                arr[i] = fr.nextInt();
            }

            int[] ans = solveOneCase(n, arr);

            for (int k = 1; k <= n; k++) {
                if (k > 1) {
                    sb.append(' ');
                }
                sb.append(ans[k]);
            }
            sb.append('\n');
        }

        System.out.print(sb.toString());
    }

    // 使用 BufferedReader + StringTokenizer 进行输入
    static class FastReader {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}
